// FOSSBilling Phase 5 R5j: DDL emitters for the generated schema
// definitions (install-schema.ts). These reproduce Doctrine DBAL 4.5's
// per-platform CREATE TABLE / CREATE INDEX / ALTER TABLE output
// byte-for-byte — the installer-test proves it against
// captures46/php-platform-ddl.json for all 63 tables on both platforms,
// so the TS installer creates exactly the schema PHP's SchemaInstaller
// creates, not a lookalike.
//
// Modifier order matters and mirrors Doctrine: TYPE, then
// PRIMARY KEY AUTOINCREMENT (SQLite) / GENERATED BY DEFAULT AS IDENTITY
// (Postgres), then DEFAULT, then NOT NULL. Postgres puts the PK in a
// table-level clause and FKs in trailing ALTER TABLE statements;
// SQLite inlines the PK (except session, table-level on both) and the
// FKs in the CREATE TABLE.
import {
  INSTALL_SCHEMA,
  type InstallColumn,
  type InstallTable,
} from "./install-schema";

const q = (name: string, quote?: boolean): string =>
  quote ? `"${name}"` : name;

function sqliteType(c: InstallColumn): string {
  switch (c.doctrine) {
    case "bigint": return "BIGINT";
    case "integer": return "INTEGER";
    case "smallint": return "SMALLINT";
    case "string": return `VARCHAR(${c.length})`;
    case "text": return "CLOB";
    case "json": return "CLOB";
    case "blob": return "BLOB";
    case "boolean": return "BOOLEAN";
    case "datetime": return "DATETIME";
    case "date": return "DATE";
    case "decimal": return `NUMERIC(${c.precision}, ${c.scale})`;
  }
}

function pgType(c: InstallColumn): string {
  switch (c.doctrine) {
    case "bigint": return "BIGINT";
    case "integer": return "INT";
    case "smallint": return "SMALLINT";
    case "string": return `VARCHAR(${c.length})`;
    case "text": return "TEXT";
    case "json": return "JSON";
    case "blob": return "BYTEA";
    case "boolean": return "BOOLEAN";
    case "datetime": return "TIMESTAMP(0) WITHOUT TIME ZONE";
    case "date": return "DATE";
    case "decimal": return `NUMERIC(${c.precision}, ${c.scale})`;
  }
}

function columnOf(table: InstallTable, name: string): InstallColumn {
  const col = table.columns.find((c) => c.name === name);
  if (!col) throw new Error(`install-schema-ddl: unknown column ${table.name}.${name}`);
  return col;
}

function tableOf(name: string): InstallTable {
  const table = INSTALL_SCHEMA.find((t) => t.name === name);
  if (!table) throw new Error(`install-schema-ddl: unknown table ${name}`);
  return table;
}

function sqliteColumn(c: InstallColumn): string {
  // Doctrine's SQLite platform renders EVERY autoincrement PK as
  // INTEGER PRIMARY KEY AUTOINCREMENT (only INTEGER is a rowid alias),
  // even when the Doctrine type is bigint.
  let s = `${q(c.name, c.quoteSqlite)} ${c.pk && c.autoinc ? "INTEGER" : sqliteType(c)}`;
  if (c.pk && c.autoinc) s += " PRIMARY KEY AUTOINCREMENT";
  if (c.defaultSqlite !== null) s += ` DEFAULT ${c.defaultSqlite}`;
  if (c.notNull) s += " NOT NULL";
  return s;
}

function pgColumn(c: InstallColumn): string {
  let s = `${q(c.name, c.quotePg)} ${pgType(c)}`;
  if (c.autoinc) s += " GENERATED BY DEFAULT AS IDENTITY";
  if (c.defaultPg !== null) s += ` DEFAULT ${c.defaultPg}`;
  if (c.notNull) s += " NOT NULL";
  return s;
}

function sqliteFk(t: InstallTable, fk: InstallTable["foreignKeys"][number]): string {
  const ref = tableOf(fk.refTable);
  const cols = fk.columns.map((c) => q(c, columnOf(t, c).quoteSqlite)).join(", ");
  const refCols = fk.refColumns.map((c) => q(c, columnOf(ref, c).quoteSqlite)).join(", ");
  return (
    `CONSTRAINT ${fk.name} FOREIGN KEY (${cols}) REFERENCES ${q(fk.refTable, ref.quoteSqlite)} (${refCols})` +
    (fk.onDelete === "CASCADE" ? " ON DELETE CASCADE" : "") +
    " NOT DEFERRABLE INITIALLY IMMEDIATE"
  );
}

function pgAlter(t: InstallTable, fk: InstallTable["foreignKeys"][number]): string {
  const ref = tableOf(fk.refTable);
  const cols = fk.columns.map((c) => q(c, columnOf(t, c).quotePg)).join(", ");
  const refCols = fk.refColumns.map((c) => q(c, columnOf(ref, c).quotePg)).join(", ");
  return (
    `ALTER TABLE ${q(t.name, t.quotePg)} ADD CONSTRAINT ${fk.name} FOREIGN KEY (${cols}) REFERENCES ${q(fk.refTable, ref.quotePg)} (${refCols})` +
    (fk.onDelete === "CASCADE" ? " ON DELETE CASCADE" : "") +
    " NOT DEFERRABLE"
  );
}

function indexStmt(t: InstallTable, ix: InstallTable["indexes"][number], platform: "sqlite" | "pg"): string {
  const cols = ix.columns
    .map((c) => q(c, columnOf(t, c)[platform === "sqlite" ? "quoteSqlite" : "quotePg"]))
    .join(", ");
  return `CREATE ${ix.unique ? "UNIQUE " : ""}INDEX ${ix.name} ON ${q(t.name, platform === "sqlite" ? t.quoteSqlite : t.quotePg)} (${cols})`;
}

/** SQLite statements for one table: CREATE TABLE (FKs inline) + indexes. */
export function emitCreateTableSqlite(t: InstallTable): string[] {
  const parts = t.columns.map(sqliteColumn);
  if (t.primaryKey.length > 0) {
    parts.push(
      `PRIMARY KEY (${t.primaryKey.map((c) => q(c, columnOf(t, c).quoteSqlite)).join(", ")})`,
    );
  }
  for (const fk of t.foreignKeys) parts.push(sqliteFk(t, fk));
  const stmts = [`CREATE TABLE ${q(t.name, t.quoteSqlite)} (${parts.join(", ")})`];
  for (const ix of t.indexes) stmts.push(indexStmt(t, ix, "sqlite"));
  return stmts;
}

/** Postgres statements for one table: CREATE TABLE (PK table-level) + indexes + FK ALTERs. */
export function emitCreateTablePostgres(t: InstallTable): string[] {
  const parts = t.columns.map(pgColumn);
  const pkCols = t.columns.filter((c) => c.pk).map((c) => c.name);
  parts.push(
    `PRIMARY KEY (${pkCols.map((c) => q(c, columnOf(t, c).quotePg)).join(", ")})`,
  );
  const stmts = [`CREATE TABLE ${q(t.name, t.quotePg)} (${parts.join(", ")})`];
  for (const ix of t.indexes) stmts.push(indexStmt(t, ix, "pg"));
  for (const fk of t.foreignKeys) stmts.push(pgAlter(t, fk));
  return stmts;
}

/** All 63 tables, in definition order (alphabetical). */
export function emitFullSchemaSqlite(): string[] {
  return INSTALL_SCHEMA.flatMap(emitCreateTableSqlite);
}

/**
 * All 63 tables for Postgres, with one execution-order adaptation over
 * the per-table output: every CREATE TABLE + index runs BEFORE any FK
 * ALTER. Per-table emission is alphabetical (invoice before
 * pay_gateway), and a FK ALTER fails on real Postgres when the
 * referenced table does not exist yet — so the installer defers all
 * ALTERs to the end. The final schema is identical to Doctrine's (same
 * tables, columns, indexes, FKs); only the execution order differs, and
 * the per-table byte-equality proof (emitCreateTablePostgres) is
 * unaffected. SQLite needs no such deferral (FKs are inline and
 * unchecked at CREATE time).
 */
export function emitFullSchemaPostgres(): string[] {
  const creates: string[] = [];
  const alters: string[] = [];
  for (const t of INSTALL_SCHEMA) {
    const stmts = emitCreateTablePostgres(t);
    for (const stmt of stmts) {
      if (stmt.startsWith("ALTER TABLE")) alters.push(stmt);
      else creates.push(stmt);
    }
  }
  return [...creates, ...alters];
}
